import os
import subprocess
import tempfile
from flask import Flask, request, jsonify
from functools import wraps
import hashlib
import hmac

app = Flask(__name__)

WEBHOOK_SECRET = os.environ.get('WEBHOOK_SECRET', '')
ALLOWED_REPOS = os.environ.get('ALLOWED_REPOS', 'org/frontend,org/backend').split(',')
WORKDIR = os.environ.get('BUILD_WORKDIR', '/tmp/builds')

def verify_signature(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        signature = request.headers.get('X-Hub-Signature-256', '')
        if WEBHOOK_SECRET:
            expected = 'sha256=' + hmac.new(
                WEBHOOK_SECRET.encode(), request.data, hashlib.sha256
            ).hexdigest()
            if not hmac.compare_digest(signature, expected):
                return jsonify({'error': 'invalid signature'}), 403
        return f(*args, **kwargs)
    return decorated

def sanitize_branch(branch):
    """Basic sanitization - removes obvious shell metacharacters"""
    forbidden = [';', '&&', '||', '`', '$(']
    for char in forbidden:
        if char in branch:
            return None
    if len(branch) > 128:
        return None
    return branch

def get_clone_depth(payload):
    """Determine clone depth based on commit count"""
    commits = payload.get('commits', [])
    if len(commits) > 10:
        return 50
    return 1

@app.route('/webhook/push', methods=['POST'])
@verify_signature
def handle_push():
    payload = request.get_json()
    if not payload:
        return jsonify({'error': 'no payload'}), 400

    repo_name = payload.get('repository', {}).get('full_name', '')
    if repo_name not in ALLOWED_REPOS:
        return jsonify({'error': 'repo not allowed'}), 403

    ref = payload.get('ref', '')
    if not ref.startswith('refs/heads/'):
        return jsonify({'error': 'not a branch push'}), 400

    branch = ref.replace('refs/heads/', '')
    branch = sanitize_branch(branch)
    if branch is None:
        return jsonify({'error': 'invalid branch name'}), 400

    clone_url = payload.get('repository', {}).get('clone_url', '')
    if not clone_url.startswith('https://github.com/'):
        return jsonify({'error': 'invalid clone url'}), 400

    depth = get_clone_depth(payload)
    build_dir = tempfile.mkdtemp(dir=WORKDIR)

    # Clone and run build
    clone_cmd = f"git clone --depth {depth} --branch {branch} {clone_url} {build_dir}/src"
    try:
        result = subprocess.run(
            clone_cmd,
            shell=True,
            capture_output=True,
            timeout=120,
            cwd=WORKDIR
        )
        if result.returncode != 0:
            return jsonify({'error': 'clone failed', 'stderr': result.stderr.decode()[:500]}), 500
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'clone timeout'}), 504

    # Run build script from repo
    build_script = os.path.join(build_dir, 'src', '.ci', 'build.sh')
    if os.path.exists(build_script):
        build_result = subprocess.run(
            ['bash', build_script],
            capture_output=True,
            timeout=300,
            cwd=os.path.join(build_dir, 'src'),
            env={**os.environ, 'CI': 'true', 'BRANCH': branch}
        )
        return jsonify({
            'status': 'built',
            'exit_code': build_result.returncode,
            'stdout': build_result.stdout.decode()[:2000]
        })

    return jsonify({'status': 'cloned', 'branch': branch})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    os.makedirs(WORKDIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
